import queue, threading

work = queue.Queue(maxsize=8)
results = queue.Queue()
SENTINEL = object()

def consumer():
    while True:
        item = work.get()
        if item is SENTINEL:
            work.task_done()
            return
        results.put(item * item)
        work.task_done()

workers = [threading.Thread(target=consumer) for _ in range(3)]
for w in workers:
    w.start()
for n in range(20):
